scenarios.example_code:
import { createTicket } from '@projexlight/sdk-service-request';
const { ticket_id, assigned_queue } = await createTicket({
  tenant_id, requester_persona_id, kind: 'billing-question',
  subject: 'Why was I charged twice?', body, priority: 'normal',
});

subscribeEvents('conversation.session.opened.v1', async (e) => {
  if (e.payload.kind !== 'support') return;
  await createTicket({ requester_persona_id: e.payload.contact_persona_id, kind: 'inbound-chat', body: e.payload.first_message });
});

import { assignTicket } from '@projexlight/sdk-service-request';
await assignTicket({
  ticket_id, new_assignee_persona_id, reason: 'original-rep-ooo',
});

import { transitionTicket } from '@projexlight/sdk-service-request';
await transitionTicket({
  ticket_id, to_state: 'resolved',
  execution_refs: [{ kind: 'payment.refund', id: refund_id }],
  resolved_by_persona_id, summary: 'duplicate charge refunded',
});
